INSERT INTO dashboard_templates (key, name, description, category, definition, created_at, updated_at)
VALUES ('traceway-agent', 'Traceway Fix Agent', 'Queue, outcomes and cost of the fix agent of a monitored Traceway instance', 'traceway', '{"schemaVersion":1,"widgets":[{"title":"Queued Attempts","widgetType":"area_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.queued","aggregation":"avg"}]}},{"title":"Active Attempts","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.active","aggregation":"avg"}]}},{"title":"Waiting for Approval","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.pending_approval","aggregation":"avg"}]}},{"title":"Waiting for an Answer","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.needs_input","aggregation":"avg"}]}},{"title":"Attempts Started","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.started.delta","aggregation":"sum"}]}},{"title":"Attempts Finished","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.finished.delta","aggregation":"sum"}]}},{"title":"Attempts Failed","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.finished.failed.delta","aggregation":"sum"}]}},{"title":"Lease Reclaims","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.reclaimed.delta","aggregation":"sum"}]}},{"title":"Cost (USD)","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.cost_usd.delta","aggregation":"sum"}]}},{"title":"Runners Online","widgetType":"line_chart","config":{"sources":[{"type":"metric","name":"traceway.agent.runners_online","aggregation":"avg"}]}}]}', NOW(), NOW())
